```cpp
// P1AM-100: Motor start/stop with seal-in logic.
// Slot 1: Discrete Input Module
//   Channel 1: Start Button (Normally Open)
//   Channel 2: Stop Button (Normally Closed)
// Slot 2: Discrete Output Module
//   Channel 1: Motor Contactor Coil

#include <P1AM.h>

const int inputSlot = 1;
const int outputSlot = 2;
const int startPin = 1;
const int stopPin = 2;
const int motorPin = 1;

bool motorRunning = false;

void setup() {
  Serial.begin(115200);
  // Initialize the P1AM bus
  while (!P1.init()) {
    // Wait for modules to initialize
  }
}

void loop() {
  // Read inputs
  // Start is NO: true when pressed
  bool startPressed = P1.readDiscrete(inputSlot, startPin);

  // Stop is NC: true when NOT pressed (circuit closed)
  bool stopPressed = !P1.readDiscrete(inputSlot, stopPin);

  // Seal-in logic:
  // Motor runs if (Start is pressed OR Motor is already running)
  // AND (Stop is NOT pressed)
  if (startPressed || motorRunning) {
    if (stopPressed) {
      motorRunning = true;
    } else {
      motorRunning = false;
    }
  } else {
    motorRunning = false;
  }

  // Write output
  // Set motor contactor based on the logic state
  P1.writeDiscrete(motorRunning, outputSlot, motorPin);
}
```

